# Regenerate tables and graphics from the frozen development records; no fits.
args<-commandArgs(TRUE)
directory<-if(length(args))args[1L] else "benchmarks/ordinal-uncertainty-validation/development-v1"
s<-read.csv(file.path(directory,"summary.csv"),stringsAsFactors=FALSE)
f<-read.csv(file.path(directory,"fit-records.csv"),stringsAsFactors=FALSE)
p<-read.csv(file.path(directory,"point-summary.csv"),stringsAsFactors=FALSE)
b<-readRDS(file.path(directory,"bootstrap-diagnostics.rds"))
scenario.order<-c("regular","small","rare_endpoint","correlated_predictors","independent_clusters")
interval.order<-c("model","HC0","HC1","bootstrap")
fmt<-function(z,d=3L)ifelse(is.finite(z),formatC(z,format="f",digits=d),"NA")
coverage<-function(x,se)ifelse(is.finite(x),paste0(fmt(x)," (",fmt(se),")"),"NA")
mdtable<-function(z) {
    z[]<-lapply(z,as.character)
    c(paste0("| ",paste(names(z),collapse=" | ")," |"),paste0("| ",paste(rep("---",ncol(z)),collapse=" | ")," |"),
      apply(z,1L,function(row)paste0("| ",paste(row,collapse=" | ")," |")))
}
order.rows<-function(z)z[order(match(z$scenario,scenario.order),match(z$estimator,c("ML","meanBR")),match(z$interval,interval.order)),]
lines<-c("# Ordinal uncertainty development results","",
    "Generated by `report.R` from the complete stored records. Methods and interval rules were fixed before the main run; no production estimator or uncertainty formula was changed.","",
    sprintf("The main panel contains %d datasets and %d original fits. Each converged original fit requested 199 bootstrap refits. All five cells contain 200 paired datasets.",length(unique(paste(f$scenario,f$replicate))),nrow(f)),"",
    "Coverage is reported conditional on an interval being available. `Available and covers` is the probability of obtaining a covering interval, including unavailable results as absence of a covering result. These are distinct quantities. Parentheses contain Monte Carlo standard errors. Finite bootstrap percentile sampling error is additional to the between-dataset uncertainty described by those Monte Carlo standard errors.","")
fitgroups<-split(f,interaction(f$scenario,f$estimator,drop=TRUE))
fit.table<-do.call(rbind,lapply(fitgroups,function(z) {
    bb<-b[b$scenario==z$scenario[1]&b$estimator==z$estimator[1],]
    data.frame(scenario=z$scenario[1],estimator=z$estimator[1],original.converged=sum(z$converged),
      original.empty=sum(z$original.empty),bootstrap.summaries=sum(z$bootstrap.available),
      bootstrap.refits=nrow(bb),refits.not.converged=sum(!bb$converged),refits.with.empty.categories=sum(bb$has.empty.categories,na.rm=TRUE))
}))
fit.table<-fit.table[order(match(fit.table$scenario,scenario.order),match(fit.table$estimator,c("ML","meanBR"))),]
write.csv(fit.table,file.path(directory,"availability-failures.csv"),row.names=FALSE)
lines<-c(lines,"## Fit and bootstrap availability","",mdtable(fit.table),"",
    "Original-fit nonconvergence or failure is separate from unavailable bootstrap summaries. A bootstrap refit can converge and still contain an empty category; the package retains its point estimate but withholds regular uncertainty summaries. Refit-empty counts and nonconvergence counts can overlap.","")
cell<-function(scenario,estimator,interval,parameter="x1")
    s[s$scenario==scenario&s$estimator==estimator&s$interval==interval&s$parameter==parameter,,drop=FALSE]
paired<-read.csv(file.path(directory,"paired-differences.csv"),stringsAsFactors=FALSE)
regular<-s[s$scenario=="regular"&s$parameter=="x1",]
rare.ml<-cell("rare_endpoint","ML","bootstrap");rare.br<-cell("rare_endpoint","meanBR","bootstrap")
cl.ml<-cell("independent_clusters","ML","model");cl.br<-cell("independent_clusters","meanBR","model")
cl.hc.ml<-cell("independent_clusters","ML","HC1");cl.hc.br<-cell("independent_clusters","meanBR","HC1")
cl.boot.ml<-cell("independent_clusters","ML","bootstrap");cl.boot.br<-cell("independent_clusters","meanBR","bootstrap")
delta<-paired[paired$scenario=="independent_clusters"&paired$parameter=="x1"&paired$comparison=="HC1-model",]
lines<-c(lines,"## Interpretation","",
    sprintf("In the regular independent-observation cell, first-slope coverage ranged from %s to %s across the fixed procedures, with Monte Carlo standard errors from %s to %s. This panel gives no clear ranking among these procedures in that setting. It does not establish equivalence.",
        fmt(min(regular$conditional.coverage)),fmt(max(regular$conditional.coverage)),
        fmt(min(regular$conditional.coverage.mcse)),fmt(max(regular$conditional.coverage.mcse))),"",
    sprintf("Rare-category bootstrap availability was the main practical limitation: only %d of 200 ML and %d of 200 meanBR datasets received percentile intervals. MeanBR retained finite original fits, but finite estimates did not prevent resampled empty categories. Conditional coverage on these small selected subsets cannot support a general rare-category calibration claim. A zero plug-in Monte Carlo standard error after no observed misses also does not imply that coverage is known precisely.",rare.ml$available,rare.br$available),"",
    sprintf("For the clustered cell, first-slope model-based coverage was %s for ML and %s for meanBR. Cluster HC1 coverage was %s and %s, respectively; the paired gains over the independence-based comparator were %s (MCSE %s) and %s (MCSE %s). These differences support accounting for clustering in this design. The finite-sample accuracy of the cluster approximation remains distinct from that improvement.",
        fmt(cl.ml$conditional.coverage),fmt(cl.br$conditional.coverage),fmt(cl.hc.ml$conditional.coverage),fmt(cl.hc.br$conditional.coverage),
        fmt(delta$conditional.coverage.difference[delta$estimator=="ML"]),fmt(delta$conditional.difference.mcse[delta$estimator=="ML"]),
        fmt(delta$conditional.coverage.difference[delta$estimator=="meanBR"]),fmt(delta$conditional.difference.mcse[delta$estimator=="meanBR"])),"",
    sprintf("Whole-cluster percentile coverage for the first slope was %s (MCSE %s) for ML and %s (MCSE %s) for meanBR. Thus the percentile procedure did not attain nominal coverage in the observed panel, despite all its intervals being available. This is evidence of a finite-sample limitation to investigate, rather than a reason to tune the critical value or discard refits. Two hundred datasets and 199 bootstrap draws limit the precision of that assessment.",
        fmt(cl.boot.ml$conditional.coverage),fmt(cl.boot.ml$conditional.coverage.mcse),
        fmt(cl.boot.br$conditional.coverage),fmt(cl.boot.br$conditional.coverage.mcse)),"",
    "The result supports retaining explicit category-support and cluster-approximation limits. It does not justify changing an inference default. The next substantive questions are uncertainty at sparse category boundaries and calibration with varying numbers of independent clusters; probability-model misspecification requires a separate study with a verified pseudo-true target. No additional scenarios or estimator changes were introduced after inspecting this panel.","")
lines<-c(lines,"Bootstrap availability also depends on the fixed number of refits: the chance of encountering at least one empty-category resample increases as more refits are drawn. Reducing the number of refits to avoid that event would not establish valid uncertainty. A target-specific justification that distinguishes retained empty endpoints under meanBR from interior-category collapse is a separate theoretical task.","")
for(par in c("x1","threshold:1|2")) {
    z<-order.rows(s[s$parameter==par,])
    tab<-data.frame(Scenario=z$scenario,Estimator=z$estimator,Interval=z$interval,Available=paste0(z$available,"/",z$datasets),
        `Conditional coverage (MCSE)`=coverage(z$conditional.coverage,z$conditional.coverage.mcse),
        `Available and covers (MCSE)`=coverage(z$available.and.covered,z$joint.mcse),
        `Mean width (MCSE)`=coverage(z$mean.width,z$width.mcse),check.names=FALSE)
    lines<-c(lines,paste0("## ",if(par=="x1")"First common slope" else "First threshold"),"",mdtable(tab),"")
}
z<-p[p$parameter=="x1",];z<-z[order(match(z$scenario,scenario.order),match(z$estimator,c("ML","meanBR"))),]
tab<-data.frame(Scenario=z$scenario,Estimator=z$estimator,`Converged finite points`=z$converged.finite,
    `Bias (MCSE)`=coverage(z$bias,z$bias.mcse),RMSE=fmt(z$rmse),`Empirical SD`=fmt(z$empirical.sd),
    `All finite point count`=z$all.finite,`All finite RMSE`=fmt(z$all.finite.rmse),check.names=FALSE)
lines<-c(lines,"## First-slope point accuracy","",mdtable(tab),"",
    "Converged-point summaries can condition on different subsets for ML and meanBR. `paired-estimators.csv` separately compares squared errors on datasets where both original fits converged. All finite point estimates are retained, including those returned without convergence.","",
    "## Scope of the result","",
    "These are marginal 95% intervals for four-category models with two predictors. The full parameter tables, directional misses, conditional widths, paired contrasts with Monte Carlo standard errors, and simultaneous-inclusion diagnostics are in the accompanying CSV files. All-five-parameter inclusion is descriptive because no simultaneous 95% procedure is used.","",
    "The independent-cluster cell has a correctly specified marginal proportional-odds model but dependent outcomes. Its expected-Fisher Wald variance ignores that dependence and is included as a diagnostic comparator. HC0/HC1 use cluster sums; the whole-cluster bootstrap resamples independent clusters. Thirty clusters need not suffice for the large-cluster approximation.","",
    "This bounded development panel does not establish calibration under probability-model misspecification, with very few clusters, at structural empty-category boundaries, in growing dimension, or across arbitrary predictor distributions. A coverage difference comparable to its Monte Carlo uncertainty is inconclusive. No interval default is changed from these results.","",
    "`audit.txt` records complete-grid and failure-policy checks. `manifest.rds`, the archived `runner.R`, `installed-hashes.csv`, `source-hashes.csv`, and `session-info.txt` identify the run. All failures are present in raw records and diagnostics.")
writeLines(lines,file.path(directory,"RESULTS.md"))
raw.files<-list.files(file.path(directory,"records"),pattern="\\.rds$",full.names=TRUE)
elapsed<-sum(vapply(raw.files,function(file)readRDS(file)$elapsed,numeric(1)))
writeLines(c(paste("Sum of saved dataset elapsed seconds:",elapsed),
    "This is computational accounting, not an isolated performance benchmark; other development work was allowed.",
    "Peak memory was not measured; no scaling claim is made from this small panel."),file.path(directory,"runtime.txt"))
# Static publication-style diagnostic, retaining availability separately from coverage.
pdf(file.path(directory,"coverage-availability.pdf"),width=12,height=9,bg="white")
par(mfrow=c(2,2),mar=c(7,4,3,1),oma=c(0,0,2,0))
colors<-c("#222222","#0072B2","#009E73","#D55E00")
for(parname in c("x1","threshold:1|2")) for(est in c("ML","meanBR")) {
    zz<-s[s$parameter==parname&s$estimator==est,]
    plot(NA,xlim=c(.5,5.5),ylim=c(0,1.04),xaxt="n",xlab="",ylab="Probability",main=paste(est,parname))
    axis(1,at=1:5,labels=c("Regular","Small","Rare endpoint","Correlated X","Clusters"),las=2)
    abline(h=.95,lty=3,col="gray50")
    for(j in seq_along(interval.order)) {
        v<-zz[zz$interval==interval.order[j],];v<-v[match(scenario.order,v$scenario),]
        x<-(1:5)+(j-2.5)*.13
        segments(x,pmax(0,v$conditional.coverage-1.96*v$conditional.coverage.mcse),x,
                 pmin(1,v$conditional.coverage+1.96*v$conditional.coverage.mcse),col=colors[j])
        points(x,v$conditional.coverage,pch=16,col=colors[j])
        points(x,v$availability,pch=1,col=colors[j])
    }
    legend("bottomleft",legend=c(interval.order,"filled: conditional coverage","open: availability"),
        col=c(colors,"black","black"),pch=c(rep(16,4),16,1),cex=.66,bty="n")
}
mtext("Ordinal uncertainty development: 200 datasets/cell; bars are +/- 1.96 Monte Carlo SE",outer=TRUE,cex=.9)
dev.off()
files<-list.files(directory,recursive=TRUE,full.names=TRUE)
files<-files[!dir.exists(files)&basename(files)!="artifact-hashes.csv"]
write.csv(data.frame(path=substring(files,nchar(directory)+2L),md5=as.character(tools::md5sum(files))),
    file.path(directory,"artifact-hashes.csv"),row.names=FALSE)
